  @override
  String get mlHowStep1Title => '你的涂鸦变成身体';

  @override
  String get mlHowStep1Body =>
      '每一笔都会按粗细盖印出来，并在相交处合并。随后细化到中心线，形成一张精确贴合你所画线条的骨骼图——圆环仍是圆环，火柴人仍是火柴人。抖动造成的短刺会被修剪，弯曲处保留关节，直线段则不保留，结果最多十八根骨骼，以便搜索能够在合理时间内完成。';

  @override
  String get mlHowStep2Title => '骨骼装上马达';

  @override
  String get mlHowStep2Body =>
      '骨骼是刚性的，通过距离约束连接在一起。两根骨骼相交处即为关节，每个关节都是一个弹簧阻尼器，追踪按正弦波摆动的目标角度：静止 + 中心 + 幅度 x sin(2π f t + 相位)。关节有强度上限，地面有普通的库仑摩擦，生物自身的动作无法改变其质心。前进必须被“推”出来。';

  @override
  String get mlHowStep3Title => '步态就是基因组';

  @override
  String get mlHowStep3Body =>
      '一个基因设定整个身体迈步的频率，然后每个关节再获得三个参数：摆动幅度、在周期中的摆动时机，以及绕哪个角度摆动。这一小把数字就是全部的“神经系统”。没有大脑在对世界做出反应，只有一个节奏，这就是为什么好的步态看起来很“固执”。';

  @override
  String get mlHowStep4Title => '每一代都有六十个同时运行';

  @override
  String get mlHowStep4Body =>
      '每个生物都有二十五秒的试跑，按行进的米数计分；头部着地的时间会被扣分；一旦越过 50 米，每节省一秒还有奖励。最好的四个原样保留，每轮加入五个全新的随机基因组以防种群停滞，其余个体则通过锦标赛选择、均匀交叉和高斯变异繁衍。';

  @override
  String get mlHowStep5Title => '然后它开始攀升';

  @override
  String get mlHowStep5Body =>
      '最佳曲线先快速上升然后趋于平缓，因为搜索已经找到一个局部技巧并在打磨它。平均曲线则参差不齐且远低于最佳线，这是变异仍在丢弃大部分尝试。重新开始会重新掷骰子，同一个身体往往会学会完全不同的步态。';

  @override
