  }

  @override
  String serverTycoonBuildRamSlotsExceeded(
    String board,
    int slots,
    int sticks,
  ) {
    String _temp0 = intl.Intl.pluralLogic(
      slots,
      locale: localeName,
      other: '$slots 个内存插槽',
    );
    String _temp1 = intl.Intl.pluralLogic(
      sticks,
      locale: localeName,
      other: '$sticks 根内存条',
    );
    return '$board 只有 $_temp0，已安装 $_temp1';
  }

  @override
  String serverTycoonBuildRamTypeMismatch(
    String stick,
    String stickType,
    String board,
    String boardType,
  ) {
    return '$stick 是 $stickType，$board 需要 $boardType';
  }

