  @override
  String aiDetectorWatermarkExplanation(int count) {
    return '文本含有 $count 个不可见字符，它们不占屏幕空间，但会随文本一起被复制粘贴。打字无法产生这些字符。luma 将这些隐藏内容识别为 Claude 的水印，因此判定会明确提及 Claude，而非仅称其为“AI 生成”。';
  }

  @override
  String get aiDetectorSignatureExplanation =>
      '文本自行表明作者身份：以产品语境提及 Claude 或 Anthropic，而非普通人名。这属于直接归属证据，其优先级高于下方所有风格统计。';

  @override
  String get aiDetectorAssistantExplanation =>
      '典型聊天助手措辞表明文本来自与模型的对话，但无法确定具体模型，因此判定不点名，仅提高分数。';

  @override
  String get aiDetectorNoWatermarkExplanation =>
      '未发现不可见水印字符或 Claude 自我指称。这不代表文本一定由人类撰写：许多生成文本没有任何签名，因此仍需进行下方风格检查。';

  @override
  String get aiDetectorBurstinessExplanationHigh =>
      '每句话的长度都很接近。人类写作通常长短交替；稳定的句长可能意味着生成器在保持统一节奏。';

  @override
  String get aiDetectorBurstinessExplanationLow =>
      '句长自然变化，这是人类作者常有的特征，也是模型较难模仿的特点。';

  @override
  String get aiDetectorPhraseExplanationHigh =>
      '这些词语和句式在模型生成文本中比日常人类写作更常见。下方每个标签都对应文本中的字面匹配。';

  @override
  String get aiDetectorPhraseExplanationLow =>
      '未发现模型常用的固定表达。这本身不支持人类写作判断，因为许多生成文本也会避开它们。因此本项不参与评分，而非降低分数。';

  @override
  String get aiDetectorExtremesExplanationHigh =>
      '没有一句话特别短，也没有一句话特别长。人们会自然地混用两者，而生成器往往停留在安全的中间范围。';

  @override
  String get aiDetectorExtremesExplanationLow =>
      '文本既有简短句，也有长句，符合未经润色的人类写作常见特点。';

  @override
  String get aiDetectorVoiceExplanationHigh =>
      '几乎没有“我”“我们”“你”、随意用语或直接提问。生成文本常采用这种疏离语气，但正式的人类写作也如此，因此其权重低于节奏检查。';

  @override
  String get aiDetectorVoiceExplanationLow =>
      '文本采用个人化语气，包含代词和随意表达，而生成文本通常不会在无提示时主动使用这些措辞。';

  @override
  String get aiDetectorFormattingExplanationHigh =>
      '文本结构类似聊天模型回答：标题、项目列表和粗体标签。复制到其他位置后，这种结构仍会保留。';

  @override
  String get aiDetectorFormattingExplanationLow =>
      '文本采用普通散文形式，而非格式化聊天回答。许多生成文本也采用散文形式，因此本项只在检测到相关结构时计分。';

  @override
  String get aiDetectorContrastExplanationHigh =>
      '先提出某种回答再予以否定的句式，例如“并非只是 X，而是 Y”“真正的问题是”，是模型常用来显得有见解的修辞手法。';

  @override
  String get aiDetectorContrastExplanationLow =>
      '未发现模型常用的先铺垫再否定句式。仅凭其缺失无法得出结论。';

  @override
  String aiDetectorOpenersExplanationHigh(int used, int total) {
    return '$total 句话中有 $used 句以正式连接词开头。模型文章使用“Moreover,”和“Furthermore,”开头的频率远高于人类。';
  }

  @override
  String get aiDetectorOpenersExplanationLow => '句子并不依赖正式连接词开头。这本身不能说明作者身份。';

  @override
  String get aiDetectorContractionsExplanationHigh =>
      '几乎没有“don’t”“it’s”等英语缩写形式。生成文本通常偏向更生硬的完整形式。';

  @override
  String get aiDetectorContractionsExplanationLow => '缩写形式的使用频率符合人类自然写作。';

  @override
  String get aiDetectorDashExplanationHigh =>
      '破折号的使用远超普通人类写作中的常见频率，是模型广为人知的习惯。';

  @override
  String get aiDetectorDashExplanationLow => '破折号使用频率在正常范围内。';

  @override
  String get aiDetectorDashExplanationNone => '未发现破折号，但这不能支持任何一方的判断。';

  @override
  String get aiDetectorPassiveExplanationHigh =>
      '大量使用“was designed to”“is considered”等被动结构，会淡化动作主体，这是生成文本的常见特征。';

  @override
  String get aiDetectorPassiveExplanationLow => '被动语态保持在正常水平，大多数生成文本也如此。';

  @override
  String get aiDetectorParagraphExplanationHigh =>
      '所有段落长度几乎一致，像是被均匀分配到容器中。人类草稿通常长短不一。';

  @override
  String get aiDetectorParagraphExplanationLow => '段落长度自然变化。';

  @override
  String aiDetectorRepeatedOpenersExplanationHigh(String word, int count) {
    return '“$word”出现在 $count 句话的开头。真实作者很少反复使用同一开头，而模板化生成常会这样做。';
  }

  @override
  String get aiDetectorRepeatedOpenersExplanationLow =>
      '句子开头多样，符合多数文本的常见特点，无论其来源如何。';

  @override
  String get aiDetectorPhraseNoMatches => '无匹配';

  @override
  String get aiDetectorPhraseSoftMatch => '弱匹配';

  @override
  String aiDetectorPhraseMatchCount(int count) {
    return '$count 处匹配';
  }

  @override
  String aiDetectorPhraseWeightedRate(String rate) {
    return '每 1000 词加权出现 $rate 次';
  }

  @override
  String get aiDetectorEvidenceNoHiddenSignature => '无隐藏字符或签名';

